// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.junit.jupiter.api.Test;

/** Placement (M5) and bounded-memo (M6) tests for the fragment tier. */
class FragmentPlacementAndMemoTest {

	private static long literal(long n) {
		return ValueIds.createId(ValueIds.T_LITERAL, n);
	}

	// ------------------------------------------------------------------
	// M5: placement
	// ------------------------------------------------------------------

	@Test
	void lowestLegalDepthIsTheShallowestCoveringDepth() {
		// depth 0 binds columns {0}, depth 1 adds {1}, depth 2 adds {2,3}
		long[] availableByDepth = { 0b0001, 0b0011, 0b1111 };
		assertThat(FragmentPlacement.lowestLegalDepth(0b0001, availableByDepth)).isEqualTo(0);
		assertThat(FragmentPlacement.lowestLegalDepth(0b0010, availableByDepth)).isEqualTo(1);
		assertThat(FragmentPlacement.lowestLegalDepth(0b0011, availableByDepth)).isEqualTo(1);
		assertThat(FragmentPlacement.lowestLegalDepth(0b1000, availableByDepth)).isEqualTo(2);
	}

	@Test
	void crossGroupRequirementsHaveNoLegalDepth() {
		// two independent sibling groups: neither lane ever sees both columns (design §5.3 case 3)
		long[] leftLane = { 0b0001, 0b0011 };
		assertThat(FragmentPlacement.lowestLegalDepth(0b0110, leftLane)).isEqualTo(FragmentPlacement.NO_LEGAL_DEPTH);
	}

	@Test
	void multiplicityTelemetrySeparatesPhysicalAndLogical() {
		long[] before = FragmentTelemetry.snapshot();
		FragmentPlacement.recordFactorizedRejection(3, 1_000_000);
		long[] after = FragmentTelemetry.snapshot();
		assertThat(after[2] - before[2]).isEqualTo(3); // physical
		assertThat(after[3] - before[3]).isEqualTo(3_000_000); // logical
	}

	// ------------------------------------------------------------------
	// M6: bounded memo
	// ------------------------------------------------------------------

	@Test
	void memoEvaluatesTheExactTierOncePerDistinctId() {
		AtomicInteger exactCalls = new AtomicInteger();
		// inner escapes everything; the exact tier accepts even payloads
		LongPredicateFragment inner = (a0, a1, a2, binding) -> PredicateStatus.ESCAPE;
		MemoizedPredicateFragment memoized = new MemoizedPredicateFragment(inner);
		FragmentBinding binding = new FragmentBinding(new long[0], (a0, a1, a2) -> {
			exactCalls.incrementAndGet();
			return ValueIds.getValue(a0) % 2 == 0;
		}, new MemoizedPredicateFragment.MemoState(16, 1 << 16));
		for (int round = 0; round < 10; round++) {
			for (long id = 0; id < 8; id++) {
				PredicateStatus status = memoized.test(literal(id), -1L, -1L, binding);
				assertThat(status).isEqualTo(id % 2 == 0 ? PredicateStatus.TRUE : PredicateStatus.FALSE);
			}
		}
		assertThat(exactCalls.get()).isEqualTo(8);
		MemoizedPredicateFragment.MemoState state = (MemoizedPredicateFragment.MemoState) binding.state;
		assertThat(state.hits()).isEqualTo(72);
		assertThat(state.misses()).isEqualTo(8);
	}

	@Test
	void memoIsBoundedAndKeepsAnsweringWhenFull() {
		AtomicInteger exactCalls = new AtomicInteger();
		LongPredicateFragment inner = (a0, a1, a2, binding) -> PredicateStatus.ESCAPE;
		MemoizedPredicateFragment memoized = new MemoizedPredicateFragment(inner);
		FragmentBinding binding = new FragmentBinding(new long[0], (a0, a1, a2) -> {
			exactCalls.incrementAndGet();
			return true;
		}, new MemoizedPredicateFragment.MemoState(4, 4));
		for (long id = 0; id < 100; id++) {
			assertThat(memoized.test(literal(id), -1L, -1L, binding)).isEqualTo(PredicateStatus.TRUE);
		}
		MemoizedPredicateFragment.MemoState state = (MemoizedPredicateFragment.MemoState) binding.state;
		// the sets stopped growing at the bound but every decision stayed exact
		assertThat(state.entries()).isLessThanOrEqualTo(4);
		assertThat(exactCalls.get()).isEqualTo(100);
	}

	@Test
	void nearAllDistinctStreamsAbandonTheMemoForm() {
		LongPredicateFragment inner = (a0, a1, a2, binding) -> PredicateStatus.ESCAPE;
		MemoizedPredicateFragment memoized = new MemoizedPredicateFragment(inner);
		FragmentBinding binding = new FragmentBinding(new long[0], (a0, a1, a2) -> true,
				new MemoizedPredicateFragment.MemoState(16, 1 << 16));
		for (long id = 0; id < 1000; id++) {
			memoized.test(literal(id), -1L, -1L, binding);
		}
		MemoizedPredicateFragment.MemoState state = (MemoizedPredicateFragment.MemoState) binding.state;
		assertThat(state.abandoned()).isTrue();
	}

	@Test
	void memoForksCopyStateForParallelWorkers() {
		MemoizedPredicateFragment.MemoState state = new MemoizedPredicateFragment.MemoState(16, 1 << 16);
		FragmentBinding binding = new FragmentBinding(new long[0], (a0, a1, a2) -> true, state);
		MemoizedPredicateFragment memoized = new MemoizedPredicateFragment(
				(a0, a1, a2, b) -> PredicateStatus.ESCAPE);
		memoized.test(literal(1), -1L, -1L, binding);
		FragmentBinding fork = binding.forkForParallelWorker();
		assertThat(fork.state).isNotSameAs(state);
		// the fork answers from its copied set without touching the original's counters
		long hitsBefore = state.hits();
		assertThat(memoized.test(literal(1), -1L, -1L, fork)).isEqualTo(PredicateStatus.TRUE);
		assertThat(state.hits()).isEqualTo(hitsBefore);
	}
}
